    def updateGrid(self):
        try:
            self._updateGrid()
            self._db_ok()
        except Exception as e:
            self._db_error(str(e))

    def _updateGrid(self):
        cols = 0
        colDetail = []
        rows = 0

        for ini_key, station_id, header in STATIONS:
            if conf.config.get('VISIBLE STATIONS', ini_key) != 'True':
                continue
            rapidParts = rapidModel2.getPartsWithRapids(station_id)
            for first, *rest in rapidParts:
                self.rapidDict[first] = rest
            list_of_ids = []
            for part in rapidParts:
                tim = part[15].strftime("%d %b") if part[15] is not None else "*"
                list_of_ids.append(part[0] + ' [' + tim + ']')
            colDetail.append(list_of_ids)
            rows = max(rows, len(list_of_ids))
            cols += 1

        self.gridJobList.ClearGrid()
        cur_rows = self.gridJobList.GetNumberRows()
        if rows > cur_rows:
            self.gridJobList.AppendRows(rows - cur_rows)
        if rows < cur_rows:
            self.gridJobList.DeleteRows(0, cur_rows - rows, True)

        cur_cols = self.gridJobList.GetNumberCols()
        if cols > cur_cols:
            self.gridJobList.AppendCols(cols - cur_cols)
        if cols < cur_cols:
            self.gridJobList.DeleteCols(0, cur_cols - cols, True)

        dateBeforeRed = datetime.datetime.now().date() + datetime.timedelta(days=2)
        for col, (_, _, header) in enumerate(s for s in STATIONS
                                             if conf.config.get('VISIBLE STATIONS', s[0]) == 'True'):
            for row, cell in enumerate(colDetail[col]):
                partID = cell.split(' ', 1)[0]
                self.gridJobList.SetCellValue(row, col, cell)
                try:
                    install_date = self.rapidDict[partID][14]
                    if install_date is not None and install_date.date() < dateBeforeRed:
                        self.gridJobList.SetCellBackgroundColour(row, col, (255, 0, 0))
                except Exception as e:
                    print(f'Error colouring {partID}: {e}')

            self.gridJobList.SetColLabelValue(col, header)
            self.gridJobList.SetColSize(col, 120)

        curX, curY = self.sizer_3.GetSize()
        self.sizer_3.SetMinSize((80 * cols, curY))
        self.Layout()

    def updateOneCol(self,col2update):
        #Get new data
        rows = 0
        if self.getLocation(col2update) in self.colHdr:
            col_index = self.colHdr.index(self.getLocation(col2update))
            list_of_ids = []
            rapidParts = rapidModel2.getPartsWithRapids(col2update)
            for first, *rest in rapidParts:
                self.rapidDict[first] = rest
            for i in range(0, len(rapidParts)):
                # if rapidParts[i][16] is None:
                if rapidParts[i][15] is None:
                    tim = "*"
                else:
                    # tim = rapidParts[i][16].strftime("%d %b")
                    tim = rapidParts[i][15].strftime("%d %b")
                list_of_ids.append(rapidParts[i][0] + ' [' + tim + ']')
            if len(list_of_ids) > rows:
                rows = len(list_of_ids)

            # Fix grid rows to required amount
            cur_rows = self.gridJobList.GetNumberRows()
            if rows > cur_rows:
                # Append rows
                self.gridJobList.AppendRows(rows-cur_rows)
            #rapidDict is dictionary with install date
            dateBeforeRed = datetime.datetime.now().date() + datetime.timedelta(days=2)
            for row in range(0, cur_rows):
                self.gridJobList.SetCellValue(row, col_index, "")
            for row in range(0, len(list_of_ids)):
                self.gridJobList.SetCellValue(row, col_index, list_of_ids[row])
                # if self.rapidDict[list_of_ids[row].split(' ', 1)[0]][15] is not None:
                #     diff = self.rapidDict[list_of_ids[row].split(' ', 1)[0]][15]
                # else:
                #     diff = None

                # if diff is not None:
                #     dateOfJob = self.rapidDict[list_of_ids[row].split(' ', 1)[0]][15].date()
                #     if dateOfJob < dateBeforeRed:
                #         self.gridJobList.SetCellBackgroundColour(row, col2update, (255, 0, 0))
                if self.rapidDict[list_of_ids[row].split(' ', 1)[0]][14] is not None:
                    diff = self.rapidDict[list_of_ids[row].split(' ', 1)[0]][14]
                else:
                    diff = None

                if diff is not None:
                    dateOfJob = self.rapidDict[list_of_ids[row].split(' ', 1)[0]][14].date()
                    if dateOfJob < dateBeforeRed:
                        self.gridJobList.SetCellBackgroundColour(row, col_index, (255, 0, 0))
            self.Layout()

